CREATE TABLE IF NOT EXISTS schema_version (version INT PRIMARY KEY, installed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sys_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password VARCHAR(200) NOT NULL, real_name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'NORMAL', token_version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS person (id BIGINT AUTO_INCREMENT PRIMARY KEY, person_code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, person_type VARCHAR(20) NOT NULL, note VARCHAR(500), enabled BOOLEAN NOT NULL DEFAULT TRUE, face_path VARCHAR(255), face_state VARCHAR(20) NOT NULL DEFAULT 'NONE', face_error VARCHAR(255), version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS family_binding (user_id BIGINT NOT NULL, person_code VARCHAR(64) NOT NULL, PRIMARY KEY(user_id, person_code));
CREATE TABLE IF NOT EXISTS camera (id BIGINT AUTO_INCREMENT PRIMARY KEY, camera_code VARCHAR(64) NOT NULL UNIQUE, camera_name VARCHAR(100) NOT NULL, location VARCHAR(255) NOT NULL, capture_source VARCHAR(500) NOT NULL, node_code VARCHAR(64) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, status VARCHAR(20) NOT NULL DEFAULT 'OFFLINE', last_seen TIMESTAMP NULL, config_json TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 1, applied_version BIGINT NOT NULL DEFAULT 0, error_message VARCHAR(255));
CREATE TABLE IF NOT EXISTS danger_zone (id BIGINT AUTO_INCREMENT PRIMARY KEY, zone_code VARCHAR(64) NOT NULL UNIQUE, camera_code VARCHAR(64) NOT NULL, zone_name VARCHAR(100) NOT NULL, points_json TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, enter_seconds DOUBLE NOT NULL DEFAULT 1, exit_seconds DOUBLE NOT NULL DEFAULT 2, version BIGINT NOT NULL DEFAULT 1, applied_version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS event (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_no VARCHAR(64) NOT NULL UNIQUE, event_type VARCHAR(32) NOT NULL, camera_code VARCHAR(64) NOT NULL, person_code VARCHAR(64), zone_code VARCHAR(64), track_id VARCHAR(64), event_time TIMESTAMP NOT NULL, description VARCHAR(1000) NOT NULL, confidence DOUBLE, score_type VARCHAR(64), location VARCHAR(255) NOT NULL, image_path VARCHAR(255), content_hash VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', event_level VARCHAR(20) NOT NULL, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_handle_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_id BIGINT NOT NULL, operator_id BIGINT NOT NULL, old_status VARCHAR(20) NOT NULL, new_status VARCHAR(20) NOT NULL, remark VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS operation_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, operation VARCHAR(80) NOT NULL, description VARCHAR(1000) NOT NULL, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS emotion_sample (id BIGINT AUTO_INCREMENT PRIMARY KEY, sample_no VARCHAR(64) UNIQUE NOT NULL, camera_code VARCHAR(64) NOT NULL, person_code VARCHAR(64) NOT NULL, emotion VARCHAR(30) NOT NULL, score DOUBLE NOT NULL, sample_time TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS track_point (id BIGINT AUTO_INCREMENT PRIMARY KEY, point_no VARCHAR(64) UNIQUE NOT NULL, camera_code VARCHAR(64) NOT NULL, track_id VARCHAR(64) NOT NULL, person_code VARCHAR(64), sample_time TIMESTAMP NOT NULL, x DOUBLE NOT NULL, y DOUBLE NOT NULL);
CREATE TABLE IF NOT EXISTS interaction_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, record_no VARCHAR(64) UNIQUE NOT NULL, camera_code VARCHAR(64) NOT NULL, elder_code VARCHAR(64) NOT NULL, worker_code VARCHAR(64) NOT NULL, start_time TIMESTAMP NOT NULL, end_time TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'CANDIDATE', reviewer_id BIGINT);
CREATE TABLE IF NOT EXISTS event_video (event_id BIGINT PRIMARY KEY, state VARCHAR(20) NOT NULL, file_path VARCHAR(255), error_message VARCHAR(255));
CREATE TABLE IF NOT EXISTS push_subscription (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, endpoint_hash VARCHAR(64) NOT NULL UNIQUE, subscription_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_job (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_id BIGINT NOT NULL, subscription_id BIGINT NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, last_error VARCHAR(255), updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(event_id, subscription_id));
CREATE TABLE IF NOT EXISTS alert_rule (event_type VARCHAR(32) PRIMARY KEY, event_level VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS geofence (id BIGINT AUTO_INCREMENT PRIMARY KEY, fence_code VARCHAR(64) NOT NULL UNIQUE, fence_name VARCHAR(100) NOT NULL, points_json TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 1, applied_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS person_device_binding (id BIGINT AUTO_INCREMENT PRIMARY KEY, person_code VARCHAR(64) NOT NULL, device_id VARCHAR(128) NOT NULL UNIQUE, device_type VARCHAR(50) DEFAULT 'BEIDOU_RTK', binding_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, enabled BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY (person_code) REFERENCES person(person_code));
CREATE TABLE IF NOT EXISTS location_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, point_no VARCHAR(64) UNIQUE NOT NULL, person_code VARCHAR(64) NOT NULL, device_id VARCHAR(128) NOT NULL, longitude DOUBLE NOT NULL, latitude DOUBLE NOT NULL, accuracy DOUBLE, altitude DOUBLE, speed DOUBLE, direction DOUBLE, sample_time TIMESTAMP NOT NULL, received_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, inside_fence BOOLEAN, fence_code VARCHAR(64), INDEX idx_person_time (person_code, sample_time), INDEX idx_sample_time (sample_time), FOREIGN KEY (person_code) REFERENCES person(person_code));
